const revokeSafeguardBlock = `-- name: RevokeSafeguardBlock :one
UPDATE safeguard_blocks SET revoked_at = now(), revoked_by = $2
WHERE hash = $1 AND revoked_at IS NULL
RETURNING hash
`

type RevokeSafeguardBlockParams struct {
	Hash      string
	RevokedBy *uuid.UUID
}

func (q *Queries) RevokeSafeguardBlock(ctx context.Context, arg RevokeSafeguardBlockParams) (string, error) {
	row := q.db.QueryRow(ctx, revokeSafeguardBlock, arg.Hash, arg.RevokedBy)
	var hash string
	err := row.Scan(&hash)
	return hash, err
}

const setUserSafeguard = `-- name: SetUserSafeguard :one
UPDATE users SET safeguard_allowance = $2, safeguard_used = $3,
    safeguard_reset_cards = $4,
    safeguard_locked_at = CASE WHEN $3 >= COALESCE($2, $5::integer)
                               THEN COALESCE(safeguard_locked_at, now()) END,
    updated_at = now()
WHERE id = $1 AND deleted_at IS NULL
RETURNING id, username, safeguard_allowance, safeguard_used, safeguard_reset_cards, safeguard_locked_at
`

type SetUserSafeguardParams struct {
	ID               uuid.UUID
	Allowance        *int32
	Used             int32
	ResetCards       int32
	DefaultAllowance int32
}

type SetUserSafeguardRow struct {
	ID                  uuid.UUID
	Username            string
	SafeguardAllowance  *int32
	SafeguardUsed       int32
	SafeguardResetCards int32
	SafeguardLockedAt   *time.Time
}

// locked_at is kept while the count stays at or above the allowance and
// cleared once it drops below; it is set when the count first reaches it.
func (q *Queries) SetUserSafeguard(ctx context.Context, arg SetUserSafeguardParams) (SetUserSafeguardRow, error) {
	row := q.db.QueryRow(ctx, setUserSafeguard,
		arg.ID,
		arg.Allowance,
		arg.Used,
		arg.ResetCards,
		arg.DefaultAllowance,
	)
	var i SetUserSafeguardRow
	err := row.Scan(
		&i.ID,
		&i.Username,
		&i.SafeguardAllowance,
		&i.SafeguardUsed,
		&i.SafeguardResetCards,
		&i.SafeguardLockedAt,
	)
	return i, err
}

const upsertSafeguardBlock = `-- name: UpsertSafeguardBlock :exec
INSERT INTO safeguard_blocks (hash, prompt, first_event_id, first_user_id, created_at)
VALUES ($1, $2, $3, $4, $5)
ON CONFLICT (hash) DO UPDATE SET prompt = EXCLUDED.prompt, first_event_id = EXCLUDED.first_event_id,
    first_user_id = EXCLUDED.first_user_id, created_at = EXCLUDED.created_at, hits = 0, last_hit_at = NULL,
    revoked_at = NULL, revoked_by = NULL
WHERE safeguard_blocks.revoked_at IS NOT NULL
`

type UpsertSafeguardBlockParams struct {
	Hash         string
	Prompt       string
	FirstEventID uuid.UUID
	FirstUserID  *uuid.UUID
	CreatedAt    time.Time
}

// A revoked entry triggered again goes back on the list (as a new entry).
func (q *Queries) UpsertSafeguardBlock(ctx context.Context, arg UpsertSafeguardBlockParams) error {
	_, err := q.db.Exec(ctx, upsertSafeguardBlock,
		arg.Hash,
		arg.Prompt,
		arg.FirstEventID,
		arg.FirstUserID,
		arg.CreatedAt,
	)
	return err
}
